    (18, 14, "ያ ሰው ድኻ ቢሆን is መተውን ንቱ ዘንድ ጸታላጳድር።"),
    (18, 15, "„ቋይገበ . በየቀኑ ደመወዙን ስሕው = ' አይሞቱም።"),
    (18, 16, "ፀሐይ ላይገበ መያዣውን መልስለት ፡ ልብሱን ቋብፀ ይደር ኣንተም ትመሪረቃለህ፡ በፈጣሪህ በእግዚአብሔርም 'ፊት' ምጽዋት ይሆንልኻል = ዛፀ'፡ ፩፱ ፳፮።"),
    (18, 17, ". ከመንድምችህ ወይም በአገርህ ካሉ ስዶቶኞች ገንዘብ ያጣ ድኻ ምንደኛ ፡ ደመወዙን አትክዳው።"),
    (
        18,
        18,
        "- ድኻ ነውና አለኝታውም ክሱ ነውና ወደ እዳዚክዳ ሔር አንዳኝይጮህብህሄ ኃጢአትም እንዳይሆንብህ ፀሐይ = Het 18 IF = ክንዱም አንዱም በበደለሙ በደል ይሞታል አንጂ ፡ ወላጆች በልጃቻቸው ልጆቻ በወላጆቻቸው በዴልይ ፪ ነገ፡ ፲8 ፪፡ ሕዝ፡ ፲፭ ፳ = os] አናት አባቱ የሞቱቦትንና ! የስደተኞችን ፡ የበል ንም ፍርድ አትለውጥ።",
    ),
    (18, 19, "በግብጽ እሣር ክንት ቱኘዥ. ዩርያ አንደነበርህ ፈጣሪሀ እግዚአብሔርም ክዚያ እንዳዳነፀ አስብ ፡ ክለዚህ ይህንን ታደርኝ ዘንድ አኻኻለሁ።"),
    (
        18,
        20,
        "ዘዳ፡ ፳8 ፳፪ 12: -- የኢርቫህን አዝመራ ብታጭድ አንዲቱን ነፎ በእርቫህ ብትዛነጋ ፓነሣት ዘንድ አቸመለጸስ ፡ ፈጣሪህ እግዚአብሔር '8አጅህ ሥራ ሁሉ ያክብርህ ዘንድ አናት አብጥ ለሞቱበት aN \"እቱ ለሞ በት ልጅና ፣ ለስደተኛ ፣ ልጅና ፡ ለስደተኛ ፡ ለባልቴትም ይሁን።",
    ),
    (18, 21, "' የወይንህን. ቦታ በቀጓምክ (በለቅም ክ) ጊዜ ፡ አጥር ተህ ትለቅም ህንድ ዳግመኛ ወደ ኋለህ አትመለስ ፡ አናት ለበልቂትም ' ይሆሁኝ።"),
    (18, 22, "አናት አበቱ ለሞቱበት ልጅና ለስደተኛ ለበልቴትም ይሆን አንጂ ዛሬትህን ጸለቅምክ ጊዜ ሕጥርተሀፀ ትልቅም ዘንድ ዳግመኛ ወደ ኋላህ አትመለስ።"),
    (19, 1, "ዘሑ ፲፱ 1s ጸን በግብጽ ምድር ስደተኛ እንደ ነበር ፈጣሪህ እግዚአብሔርም ከዚያ አንዳዳነህ (ኣጎዳወጣህ) አስብ።"),
    (19, 2, "ስለዚፀም. ይህንን ነገር ታደርግ ዘንድ እኔ እዝ'ኸለሁ።"),
