    (20, 19, "ትአዛሆን ሁሉ ትጠብቅ ዘንድ ከጽጸጤቫብም ሁሉ በኣይ ትሆን 'ሾንጅ አንደ ነገረ የራ ወገን ትሆነው ዘንድ አግዚአብሔር ዛሬ መርጤዃጃልና • ዘፀ፡.፲፪ 8።"),
    (20, 20, "ጾንይ ነረሀፀ ለፈጣሪ ጸአግዚጸብሔር የተስየህ ወኘን ትሆነው ዘንድ ታጻቁ ስም ጽቁጣልህ ! አንድትመክና ዜን ድትከብርም ጸደሪረገህ።"),
