        21,
        4,
        "ሚርና ወተት የምታፈሰውን አገር ይፅጣዥሁሇሆ ዘንድ የአባቶቻችሁ ፈጫሪ አግዚጾብሔጨር አሰጣችኋለሆ ብሎ ኳን ደሜለላቸው ዮርዳኖስን ተጃግራችሁ የኃበቶቻችቻሁ ፈጣሪ ጌስፀጫጣችሁ ወዴዚያች አገር በገበችሆ ጊዜ የዚህን ኝ ነግር ሁሎ ኔቪያ ደንጊያዎች ጳይ x= NE ፳ hs ድርዳዱናስን IN ጊሼ ክኔ እሁን ክለ አነሳቸው st, ee [itn [~~ የማዛችሁን እነዚያን ድንጊያዎኛ ጌል በሜበል ተራ. -- --- -- -- -- |; ጳይ ጴቁማሜችሁ በረንቁ (በኖራ) ቋቸው (ለቅልቋቸው)።",
