    (21, 5, "ብረት በል፣ክጀሙ ስልለዘዥ ድንጋዮች ዘፈጣሪፀ ቋኳ ማሂጸብሔር 8ዚያ መሠውያን ሥራ በነቋቸው ለፈጣሪ አግማዚይብሔር መሠሙያኝ አዘጋጅ።"),
