    (21, 10, "| ዛይ የማዝህን ትእዛዙንና ፍርዱን ሁሉ አድርግ አላቸው።"),
    (
        21,
        11,
        "ሙሴ በዚያች ቀን ሕዝቡን እንዲህ ብሎ አዘዛቸው | ርዳኖስን በተሻ፣ራችሁ ጊዜ ገሪዛን በሚባል ተራራ ላይ ቁመው ሕዝዙን የሚመርቁት አሊህ ናቸው ፤ ake ሴዊ ', ይሁዳ ፡ ይሳክር ፡ ዮሴፍና ብንያም ናቸው Bec ጌይ ጐመራ Re Ag Re. ሮቤል ፡ ጋድ ፡ ዛብሎን ፡ አሴር ፡ ንፍቃሌምና ዳን ና Ts | ' እነዚያ ሌዋውያንም ለእስራኤል ሁሉ በታላቅ ቃል እንዲህ ብለው ይመል ላቸዋል = cv በአግዚአብሔር ዘንሯ የተጠላ (ርዥስ የሆነ) የተቀረጸ. ጣኦትን የሚያደርግ ዕው ሠራቭ ጣኔትንም ሠውሮ የሚያ ኖር ሰው የተረገመ ይሁን ይበሎዋቹው ፡ ሕዝቡም ሁሱ መልስው (ዜጽሜን) ይሁን ይሁን ይበሉ = ዘ8፡ ፳ 8s \"እናት እጻሄንኝ የሚያቃልል ዕው የተረገመ ይሁን ፡ ይበሉዋቸው ቋዝቡም ሁሉ መልስው ይሁን ይሁን ይበሉ።",
    ),
    (
        21,
        12,
        "የበልንጀራውን ድንበር የሚጸርቅ i) ቋ= የተሪንኘመ ጽሁን ይበሏቸው ፡ ሕዝቡም ውሉ, መልው ይሁን ይሁን ይበሉ = F ፅፀውድን ጐዳና የሚያጻስተው የተሪኝ= ይሁን ድበሏ ቸው ፡ አዝቡም ሁሉ መልሰው ይሁን ይሁን ይጻሉ = Nr ኣናት አበቱ በሞቁክታ ልጅ ፡ በመጻተኛኝ ፡ በጻዛልቴ ቸም ፍርድ የሚ Lያይላ ሰው የተረገመ ይሁን ይበሏቸው ፡ ሕዝቡም ሁሉ መልሰው ይሁን ይሁን ዴበሉ።",
    ),
    (21, 13, "ያበቱን ኃፍረት ገልጧልና ከእንጀራ ኣናቱ የድረጳ ሰበው የተረገመ ይሁን ይበሏቸው ' ሕዝቡም ሁሉ መል ስው ይሆን ይሁን ይበሉ » ዘሴ፡ ፲፭ ፳ ፡ ዘዳ' ፳፪ ዳ።"),
