    (
        22,
        1,
        "አግዚአብሔርም ፀቤትህ ፀረክቱን ይዶክልኻል , ፈጣ. ሪሀ አግዚጾብሔሑር ስሰመህ ምድር በአጅሀ ፀያዝክው 5ንዘ ብህ ሁሉ በረከቱን ያሳድራል = ዘሔ፡ ይ = ፈጣሪህ የአግዚአብሔርን ቃል ከሰማህ ፡ ሸሕጐጕም ጺን ተህ ከክኖርሄ አግ ዚጽብሔር ቋአፀቶችህ ኣንደሜለ ቁ ዩተዮ ለየህ ወገን አድርጎ የቆግኻል = ዛ8፡ ፲፱ ፪።",
    ),
    (22, 2, "በዚሀ ዓለም ያሉ አሕዛብም ሁሎ የፈጣሪህ ዩአግዚጳኣ ብሔር ስም በአንተ አንዴ ተወራ አይተው ይፈሩሃል።"),
    (22, 3, "ፈጣሪህ አግዚጾብሔሑርም ከአብራክህ በተክፈሉ ፊይጆ ች፱ ከመድርህም በተገኘው አዝመራ 88 ረድኤት ብዙ ብዙ ያደርግኻዃል።"),
    (
        22,
        4,
        "ጠፈር በአድማስ ጸንቶ አንዲኖር ለአበቶችህ ኢንደ ማለላቸው ፈጣሪህ እግዚጾብሔር በዚህ ዓለም አጽንቶ ይኖርህ ዛንድ ክብቶችፀም እንዲዋሌዱ ያዴርጋቸወል = ምድርህ በምታበቅልበት ወራት ሰማይ ዝናም ሌዘር | ይሰጥህ ዘኔድ ፡ የአጅሀንም ሥራ ሁሉ ይቑርክፏህ ዘንድ አግዚአብሔር መልክሙን መዝገብ ማዩን ይክፍትል ኻል ፣ ዜንተ ጸብ ቋሕዛብ ታበድራለክ፣ እንተ ማኝ አት በደርም ጸኘተ ብዙ ጴሕዛብን ትነዛቸዋለህ፡ ጾንተኘ ማኝ አይ፣ዙህም = ፪ )ነነ፡ 8፪ ፪፡ ምብ፡ ፱ B፮።",
    ),
    (
        22,
        5,
        "ቫሬ ክኔ የማዝህን የፈጣማሪህ የአግዚአብሔርን ቋል ብቸፀሟ ትአዛዥንም ብትጠመብዎና ብትፈጽም ፡ እጥዚአብ ጨር ራስ ያደርግኻል እንጂ፡ ጀራት (ገዥ ያድርግኻል አያደርግህም = ኢያ ሸi።",
    ),
    (22, 6, ", ታመልክቸው ዘንድ የአሕዛብን ጣኦታት በትከተልና ክኔ ቫሬ ክዘዝሹህም ቃል ወደ ቀኝ ወይ ግራ በትል፡ - ከሁሉ በላይ ትሆናስህ አንጂ ክሁሉ በታች አትሆንም።"),
    (22, 7, "አኔ አሁን የማዝሄን ትአሻዙን ሁሉ ትጠብቅ ዘንድ ዩፈ ' ጣሪሀ የአግዚአብሔርን ቃል በትሰማ ግን ይህ ሁሉ ርግ ማን ይይደርዘብኻል ፡ መክራም ያገኛኻል።"),
    (22, 8, "አንቱ በክተማም በበረኻም የተረዎክ ትሆናለህ።"),
    (
        22,
        9,
        "ድልብሀም ገንሄብህሀም የተረገመ ይሆናል (ይጠፋል) ክጸዌራክዘ የ ተክፈለ ልጅህም የተረገመ ይሆናል ፡ ክም ድርሀ ዩተኘኘ አዝመራም ይጠፉል ፡ የበጎችሀና የላሞች ሀም መንጋ ርጉም ይሆናል (ድጠፋል)።",
    ),
    (22, 10, "| ጸንቱም በመግበትህም በመውጣትሀመ የተረገምክ ትሆናለህ።"),
    (22, 11, "| አግዚአብሔርም በንተ ረኃብን ፣ ችጋርን ቸነፈርን የመጣብዃል በአጅሀ ዩያሣክውም ሁሉ ይጠፋል ፡ እኔን ክርስቲያን ሃይማኛችና ሥርዓት | ዕራፍ ፳ሯ።"),
    (22, 12, "| ጴገር አስማርሾ ይወስድ’ኻል ፥ ft ትተኸኛልና ስል ሥራህሀ ክፋት ፈጥኖ እስኪያጠፉ ድረ ሞትን ያጠፋኻል።"),
    (22, 13, "ዘዳ፡ ፮ ዘ ፡ ሚክ ዩ፱።"),
    (
        22,
        14,
        ". . ትወርሳት ዘንድ አንተ ከምትገበበት ምድር ፈጥና አስኪያጠተፉህ ድረስ እግዚአብሔር ሞችን ORs ዘሴዋ፡ ፳፱ ፲፮ አጥፈኣብሪኤርም (በደዊ ጴ) በሆድ ዴኖ ፀኝኘዳፎ፡ (አስፈር) በቀቍርማት በፍርሃት ፡ በድንጋሂ ፡ በድርቅና እኽ ልን በሣጣት ያጠፋኻል እስኪያጠፋህም ድረስ ክገር አውጥተው ይሰዱሣል።",
    ),
    (22, 15, "ዛሌ፡ ፳፮ ፲፮ ፡ ፩ ነገ is ከራስሀ በላይ ያለች ፀማይ ናስ ትሆንብሀለች በበታ ችህ ያለች ምድርም ብረት ትሆንብህለች።"),
    (
        22,
        16,
        "እግዚአብሔርም በምድርህ ላይ የሚዛንመውን ዝናም ጽጋግ ያደርገዋል ' ፈጽሞ እስኪያጠፋህም ድረስ አፈር , (ዋግ) ከሰማይ ይወርድብኻል አግዚአብሔር በጠላትህ ፊዥ እንድትሞት ያደርግ ኻል በአንዲት ጐዳና ወዶነሳቸው . ወጥተህ ' ከፊታቸው በሰቫት ጐዳና ትሸሻላህ በአሕዛብ መንግሥታትም ሁሉ ትበተናላህ።",
    ),
    (22, 17, "| የሚቁቀብርህ አጥተህ ሬሳዎችህ ለሰማይ ወፎች ምግብ ይሆናሉ።"),
    (
        22,
        18,
        "8 ጳሙ፡ 12 3፱፡ መኽ ደ፱ ፪ = እግዚአብሔር የግብጽ ሰዎችን ባጠፋበት መቅሠ ፍት በክፉ ችፌ ጅግንነት በሌለበት እከክ ሰውነትህን ያጠፋፉኻል =. - እግዚአብሔር EE በዕውርነት (በድንብር ብር) በልዙናም ድንጋጤ ያጠፉህል = ዘዳ! ፳ጽሯቿ ፪ = .ፅውር በጨለማ እንዲርመሰመስ ተመልሰሆ በጥን ትርመሰመሳላህ መንገድም ኣእታገኝም ፡ በዛቫመንህም ሁሉ የተገፋህ የተዛረፍፀም ትሆናለህ የሚረዳህንም አታገጃም።",
    ),
    (22, 19, "ሚስት ታኝጓለህክ ሌላም ሰው ይቀማ-ጓል ፡ ቤትም ትሠራለህ ጸችትኖርበትም ፡ ወይንን ትተክላለህ ፡ ነግር ግኝ ፍሬውን አትለቅም ም።"),
    (22, 20, "ዘዳ፡ ጃጀ ጀ-፤፡ክ8።"),
    (22, 21, "በሬህን ያየርዱቻል. ነገር ግን ከሥጋው ጽቋቸፀላም ላህያ)ን ይቀሙዃኻል ኣይመል ሱቡልህም ፡ በጎችህን ፀመላቶ ችህና ለባሮችህ አሳልፈው ይጣሉ የሚረዳህም አቻኘኝም።"),
    (
        22,
        22,
        'ወንዶች, ልጃችህና ቶች ፊይጆችህ ተማርከው ወድ አሕዛብ ይሄዳሉ ፡ ራስ ዳቸውን ቢቁቀመዋኖጨቸው በዓይና "ችህ ታያለህ ፡-35ር-ማን ምንም የምታድይርገው-ነንር የለም።',
    ),
    (22, 23, "ከምድርም የተገኘውን ኣዝመራህን የደም ክበት ሣግንዘብህን የማታውቀው ሕጃብ ይበላብዳኻል ፥ ጽንተም በዛ መንህ ሆሉ የተቶጨ፥ቅክና የተኘፋህ ትሆና ለህ።"),
    (22, 24, "ፍይናችህ በሚያዩት ሁሉ ትሽሽቫላህ ፡ አታይም (ምሑብ ዕብድ ትሆናለህ)።"),
    (22, 25, "ዘጫማህ ጀመሮ አኳክ ራስህ ፍረስ መዳን በማትችል ጎንዘብ አዳግዚጾብሔር ልበን ጭንህን በትህን በሚያ ' ጓብጥ በክፉ ደዌ ይመታ'ኻል።"),
    (
        22,
        26,
        "አግዚአብሔር በብዙ ሕዝብ ላይ ከሸመልህ አለቆችህ ጋር አንቀ ወደማታውቀው አበቶችህም ወደማያውቁት ዚያም ሌሎች የፅን ጨትና የጽንጋይ ኣማልኽትን ታመልክለህ = ክርስቲያን ሃይማኛችና ሥርኝኛች።",
    ),
    (22, 27, "በዚያም. የዪነንጥህ ትሆናልክ ፡ እግዚብሔር አስማ ርክ በሚወስድህ በዚያም ለአሕዛብ መተረቻ መዘበቻ ትሆናለህ።"),
    (22, 28, "በአርሽ ብዙ ዘር ዘርተህ ጥቁት ታገዩለዕ፡ አንበጣ. በልቷታልና።"),
    (
        22,
        29,
        "ሚሕ፡ ፪ ፲ዩ፡ dጌ፡ 8 = | wይን Fuh ዮል sንር ማኙ ከይሩ ኣፍ ጠጣም ፡ በሱም ይክ አይልክም ክፉ ትል በይቶታልና = በአውራጃህ ሁሉ የዘይት ወይራን ትተክላለህ ፡ ነገር ግን ፍሬው ረግፏዴልና ከሱ ዘይቱን አትቀፀም።",
    ),
    (
        22,
        30,
        "ወንዶች ልጆችንና ሴቶች ልጆትን ትወልዳለህ ፡ ነገር ግኝ ሜርከው ይወስዱዊቸዋል ፡ አያከቀኖልዶክም = . ከምድርህ የተገኘ እዝመራህን ጴታክልኝ ዘኘም ሁሉ; ሇብዀበ ያጠፋዋል።",
    ),
