    (23, 7, "ፀጻገርህ ሣለህ ጠላትህ ፀመጣብህ መከራ ሆሉ ፈጣ ረህ አግዚአብሔር የሰጠህን ከባሕርይህ የተወለዱት የሌቶች ልጆችህንና የወንዶች ልጆችህን ሥጋ ትበላሏለህ።"),
