        23,
        10,
        "| [RH R, Ln በአገሮችሀ ሁሉ ላለህ ጠላቶችህ በጸኑብሀ መክራ፡ . ምንም ምን አላስቀሩላቸውምና ይመገቡ ዘንድ ከነሳቸው ላንዱም ላንዱም የልጆቻቸውን ሥጋ ይሰጡዋቸዋል።",
