    (23, 13, "በዚህ መጽሐፍ የተጻፈ የዚህን ሕግ ነገር ሁሉ ታ li ርግ ዘንድ yy ‘የከበረና የተመሰገ የፈጣሪህ የእግዚ ብሔርን ስም ትፈራ ዘንድ በትሰማ።"),
